/////////////////////////////////////////////////////////////////////////////////////////////////////////
/////////////////////////////////////////////////////////////////////////////////////////////////////////
type User = {
  id: string
  created_at?: string
  email: string
  first_name?: string
  last_name?: string
  email_verified_at?: string
  avatar_url?: string
}

/////////////////////////////////////////////////////////////////////////////////////////////////////////
/////////////////////////////////////////////////////////////////////////////////////////////////////////
type UserProfile = User

/////////////////////////////////////////////////////////////////////////////////////////////////////////
/////////////////////////////////////////////////////////////////////////////////////////////////////////
type UserTokenResponse = {
  access_token: string
  refresh_token: string
  user: User
}

/////////////////////////////////////////////////////////////////////////////////////////////////////////
/////////////////////////////////////////////////////////////////////////////////////////////////////////
type UserCreatePayload = {
  email: string
  password: string
  first_name?: string
  last_name?: string
}

/////////////////////////////////////////////////////////////////////////////////////////////////////////
/////////////////////////////////////////////////////////////////////////////////////////////////////////
type UserUpdatePayload = {
  first_name?: string
  last_name?: string
  avatar_url?: string | null
}

/////////////////////////////////////////////////////////////////////////////////////////////////////////
/////////////////////////////////////////////////////////////////////////////////////////////////////////
type PasswordForgotPayload = {
  email: string
}

/////////////////////////////////////////////////////////////////////////////////////////////////////////
/////////////////////////////////////////////////////////////////////////////////////////////////////////
type PasswordResetPayload = {
  token: string
  new_password: string
}

/////////////////////////////////////////////////////////////////////////////////////////////////////////
/////////////////////////////////////////////////////////////////////////////////////////////////////////
type PasswordChangePayload = {
  old_password: string
  new_password: string
}

/////////////////////////////////////////////////////////////////////////////////////////////////////////
/////////////////////////////////////////////////////////////////////////////////////////////////////////
type EmailChangePayload = {
  new_email: string
}

/////////////////////////////////////////////////////////////////////////////////////////////////////////
/////////////////////////////////////////////////////////////////////////////////////////////////////////
type UserSession = {
  id: string
  created_at?: string
  last_used_at?: string
  expires_at: string
  user_agent?: string
  ip_address?: string
}

/////////////////////////////////////////////////////////////////////////////////////////////////////////
/////////////////////////////////////////////////////////////////////////////////////////////////////////
type UserSessionListResponse = {
  items: UserSession[]
  total: number
  page: number
  size: number
  pages: number
}

/////////////////////////////////////////////////////////////////////////////////////////////////////////
/////////////////////////////////////////////////////////////////////////////////////////////////////////
type SessionsLogoutResponse = {
  revoked: number
}
